/* Admin console + shared management helpers (content editing, evaluation) also used by the trainer panel.
   Convention: record ids shown in inline handlers are always server/uid generated (safe); emails are never put in handlers. */
FS.chart=(items,suffix)=>`<div class="chart">${items.map(i=>`<div class="b"><em>${i[1]}${suffix||''}</em><i style="height:${Math.max(3,Math.min(100,i[2]!=null?i[2]:i[1]))*.8}%"></i>${E(i[0])}</div>`).join('')}</div>`;
const sel=(name,opts,v)=>`<select name="${name}">${opts.map(o=>`<option value="${E(o[0])}" ${String(o[0])===String(v)?'selected':''}>${E(o[1])}</option>`).join('')}</select>`;
const progOpts=()=>FS.programs().map(p=>[p.id,p.name]);
const lines=v=>String(v||'').split('\n').map(x=>x.trim()).filter(Boolean);
const ta=(name,arr,ph)=>`<textarea name="${name}" rows="4" placeholder="${E(ph||'One per line')}">${E((arr||[]).join('\n'))}</textarea>`;
const stat=(i,v,l)=>`<div class="card stat"><div class="ic">${i}</div><div><b>${v}</b><span>${l}</span></div></div>`;
/* call an admin endpoint, then reload server state */
const call=async(method,url,body,msg)=>{try{const r=await FS.api(method,url,body);if(msg)FS.toast(msg);await FS.reload(true);return r}catch(e){FS.err(e)}};
/* persist local edits, then re-render */
const commit=async(msg)=>{await FS.save();if(msg)FS.toast(msg);FS.render(true)};
const delBtn=(onclick,label)=>`<button class="btn btn-d btn-sm" onclick="${onclick}">${label||'Delete'}</button>`;
const mailto=(e,l)=>`<a href="mailto:${E(e)}">${E(l||e)}</a>`;

FS.route('/admin/(\\w+)',([pg])=>{
 if(!FS.guard('admin'))return;
 const pages={overview:aOver,students:aStudents,programs:aPrograms,content:aContent,assessments:aAssess,certificates:aCerts,placement:aPlace,announcements:aAnn,staff:aStaff,inbox:aInbox,reports:aReports,settings:aSettings};
 const t={overview:'Admin Overview',students:'Students & Applications',programs:'Program Management',content:'Learning Content Management',assessments:'Assessment Management',certificates:'Certification Management',placement:'Placement Management',announcements:'Announcements',staff:'Trainers & Staff Accounts',inbox:'Contact Messages',reports:'Reports & Analytics',settings:'Site Settings'};
 if(!pages[pg]){FS.go('#/admin/overview');return}
 FS.mountPortal('admin',pg,t[pg],pages[pg]());
});

/* ================= Dashboard widgets (shared by all three panels) ================= */
FS.greet=()=>{const h=new Date().getHours();return h<12?'Good morning':h<17?'Good afternoon':'Good evening'};
FS.todayStr=()=>new Date().toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long'});
FS.ago=d=>{if(!d)return'';const n=Math.round((new Date(FS.day(0)+'T00:00:00')-new Date(d+'T00:00:00'))/864e5);return n<=0?'Today':n===1?'Yesterday':n<30?n+'d ago':FS.fmt(d)};
FS.hero=(title,sub,actions,side)=>`<div class="dhero"><div class="mesh2"><i></i><i></i></div><div class="dh-l"><span class="pill dk">${FS.todayStr()}</span><h2>${title}</h2><p>${sub}</p><div class="dh-a">${actions}</div></div>${side?`<div class="dh-r">${side}</div>`:''}</div>`;
FS.kpi=(icon,val,label,sub,href)=>`<${href?`a href="${href}"`:'div'} class="card kpi"><div class="kp-i">${icon}</div><div><b>${val}</b><span>${label}</span>${sub?`<small>${sub}</small>`:''}</div></${href?'a':'div'}>`;
FS.hbars=rows=>`<div class="hbars">${rows.map(r=>`<div class="hb"><div class="hb-t"><span>${E(r[0])}</span><b>${r[1]}</b></div><div class="hb-b"><i style="width:${r[2]}%"></i></div></div>`).join('')}</div>`;
FS.donut=(pct,label)=>`<div class="donut" style="--p:${pct}"><div><b>${pct}%</b><span>${label}</span></div></div>`;
FS.feed=items=>items.length?`<div class="feed">${items.map(i=>`<div class="fi2"><i>${i[0]}</i><div><b>${i[1]}</b><small>${i[2]}</small></div><time>${i[3]}</time></div>`).join('')}</div>`:'<div class="empty">Nothing yet</div>';
FS.seg=rows=>{const t=rows.reduce((a,r)=>a+r[1],0)||1;return `<div class="seg">${rows.map((r,i)=>`<i class="s${i}" style="flex:${r[1]/t}" title="${E(r[0])}: ${r[1]}"></i>`).join('')}</div><div class="seg-l">${rows.map((r,i)=>`<span><i class="s${i}"></i>${E(r[0])} <b>${r[1]}</b></span>`).join('')}</div>`};
FS.qa=items=>`<div class="qa">${items.map(i=>`<a href="${i[2]}" ${i[3]?`onclick="${i[3]};return false"`:''}><i>${i[0]}</i><b>${i[1]}</b></a>`).join('')}</div>`;

/* ================= Overview ================= */
function aOver(){const S=FS.state,u=FS.user(),pend=S.applications.filter(a=>['Pending','Under Review'].includes(a.status)),unread=S.messages.filter(m=>!m.read).length;
 const toReview=S.submissions.filter(s=>s.status==='Submitted').length,st=S.students,n=st.length||1;
 const wk=FS.day(-7),newSt=st.filter(s=>s.joined>=wk).length,newAp=S.applications.filter(a=>a.date>=wk).length;
 const paid=st.filter(s=>s.feeStatus==='Paid').length,paidPct=st.length?Math.round(paid/n*100):0,fee=+S.site.fee||0;
 const avg=f=>st.length?Math.round(st.reduce((a,s)=>a+f(s),0)/n):0,avP=avg(FS.progressOf),avA=avg(s=>s.attendance),avS=avg(FS.scoreOf);
 const byProg=FS.programs().map(p=>[p.name,st.filter(s=>s.program===p.id).length]),mx=Math.max(1,...byProg.map(x=>x[1]));
 const stc=k=>S.applications.filter(a=>a.status===k).length;
 const act=[...S.applications.map(a=>['📥',E(a.name)+' applied',E(FS.pname(a.program)),a.date]),...S.submissions.map(s=>['📤',E(s.name)+' submitted work',E(s.title),s.date]),
  ...S.certs.map(c=>['🏅','Certificate issued to '+E(c.name),E(c.id),c.date]),...S.messages.map(m=>['✉️','Message from '+E(m.name),E(String(m.message).slice(0,54)),m.date]),
  ...S.jobApps.map(j=>['💼',E(j.name)+' applied for a job',E((S.jobs.find(x=>x.id===j.jobId)||{}).title||''),j.date])].filter(x=>x[3]).sort((a,b)=>b[3].localeCompare(a[3])).slice(0,8).map(x=>[x[0],x[1],x[2],FS.ago(x[3])]);
 const todo=[[toReview,'📝','submissions to evaluate','#/admin/assessments'],[pend.length,'📥','applications to review','#/admin/students'],[unread,'✉️','unread messages','#/admin/inbox'],[S.certReq.length,'🏅','certificate requests','#/admin/certificates']].filter(t=>t[0]);
 return FS.hero(FS.greet()+', '+E(u.name.split(' ')[0])+' 👋','Here is what is happening across your programs today.',
   `<a class="btn btn-a" href="#/admin/students">Review applications${pend.length?` (${pend.length})`:''}</a><a class="btn btn-w" href="#/admin/announcements">Post announcement</a>`,
   `<div class="dh-stat"><b data-n="${st.length}">${st.length}</b><span>students enrolled</span></div>`)+`
 <div class="grid g4 kpis">${FS.kpi('👥',st.length,'Registered students',`+${newSt} this week`,'#/admin/students')}${FS.kpi('📥',pend.length,'Pending applications',`+${newAp} this week`,'#/admin/students')}${FS.kpi('🏅',S.certs.length,'Certificates issued',S.certReq.length+' requested','#/admin/certificates')}${FS.kpi('💰','₹'+(paid*fee).toLocaleString('en-IN'),'Fees collected',paid+' of '+st.length+' paid','#/admin/students')}</div>
 <div class="grid g3 dgrid">
  <div class="card"><div class="ch-h"><h3>Enrollment by program</h3></div>${FS.hbars(byProg.map(x=>[x[0],x[1],Math.round(x[1]/mx*100)]))}</div>
  <div class="card"><div class="ch-h"><h3>Learning health</h3></div><div class="donuts"><div>${FS.donut(avP,'Progress')}</div><div>${FS.donut(avA,'Attendance')}</div><div>${FS.donut(avS,'Avg score')}</div></div><p class="hint" style="text-align:center;margin-top:10px">Averages across all students</p></div>
  <div class="card"><div class="ch-h"><h3>Fee collection</h3></div><div class="row" style="gap:18px">${FS.donut(paidPct,'paid')}<div style="flex:1"><div class="hint">Collected</div><b class="big">₹${(paid*fee).toLocaleString('en-IN')}</b><div class="hint" style="margin-top:8px">Pending</div><b>₹${((st.length-paid)*fee).toLocaleString('en-IN')}</b></div></div></div></div>
 <div class="grid g2 dgrid">
  <div class="card"><div class="ch-h"><h3>Application pipeline</h3></div>${FS.seg([['Pending',stc('Pending')],['Under review',stc('Under Review')],['Approved',stc('Approved')],['Rejected',stc('Rejected')]])}
   <div class="ch-h" style="margin-top:22px"><h3>Awaiting review</h3><a class="btn btn-o btn-sm" href="#/admin/students">Manage</a></div>${pend.slice(0,5).map(a=>`<div class="li"><div class="av sm">${E(initials(a.name))}</div><div style="flex:1"><b>${E(a.name)}</b><br><span class="hint">${E(FS.pname(a.program))} · ${E(a.id)}</span></div><button class="btn btn-g btn-sm" onclick="A.approve('${a.id}')">Approve</button><button class="btn btn-o btn-sm" onclick="A.reject('${a.id}')">Reject</button></div>`).join('')||'<div class="empty">All caught up 🎉</div>'}</div>
  <div class="card"><div class="ch-h"><h3>Recent activity</h3></div>${FS.feed(act)}</div></div>
 <div class="grid g2 dgrid"><div class="card"><div class="ch-h"><h3>Needs your attention</h3></div>${todo.map(t=>`<a class="todo" href="${t[3]}"><i>${t[1]}</i><div><b>${t[0]}</b> ${t[2]}</div><em>→</em></a>`).join('')||'<div class="empty">Nothing urgent. Great job! ✨</div>'}</div>
  <div class="card"><div class="ch-h"><h3>Quick actions</h3></div>${FS.qa([['➕','Add student','#/admin/students',"A.stuForm&&A.stuForm()"],['🎓','New program','#/admin/programs'],['🗂️','Add content','#/admin/content'],['🏅','Issue certificate','#/admin/certificates'],['💼','Post a job','#/admin/placement'],['📈','Export reports','#/admin/reports']])}</div></div>`}

/* ================= Applications & students ================= */
A.approve=async id=>{if(!confirm('Approve this application and create the student account?'))return;await call('POST','/api/admin/applications/'+id+'/approve',{},'Approved. Student account created')};
A.reject=id=>FS.modal(`<h3>Reject application</h3><form onsubmit="return A.doReject(event,'${id}')"><div class="fg"><label>Reason (shown to applicant)</label><textarea name="r" required></textarea></div><div class="row"><button class="btn btn-d">Reject</button><button type="button" class="btn btn-o" onclick="FS.closeModal()">Cancel</button></div></form>`);
A.doReject=async(e,id)=>{e.preventDefault();const a=FS.state.applications.find(x=>x.id===id);a.status='Rejected';a.reason=e.target.r.value;FS.closeModal();await commit('Application rejected');return false};
A.review=async id=>{FS.state.applications.find(x=>x.id===id).status='Under Review';await commit()};
A.appDel=async id=>{if(!confirm('Delete this application record permanently?'))return;FS.state.applications=FS.state.applications.filter(a=>a.id!==id);await commit('Application deleted')};
A.appView=id=>{const a=FS.state.applications.find(x=>x.id===id);
 FS.modal(`<h3>${E(a.name)} <span class="hint" style="font-weight:400">${E(a.id)}</span></h3>
 <div class="card flat" style="margin:12px 0;line-height:1.9">Email: ${mailto(a.email)}<br>Phone: ${E(a.phone)}<br>City: ${E(a.city)}<br>College: ${E(a.college)} · ${E(a.qualification)} · ${E(a.year)}<br>Program: <b>${E(FS.pname(a.program))}</b><br>Applied: ${FS.fmt(a.date)}<br>Resume: ${a.resumeId?`<a href="${FS.fileUrl(a.resumeId,1)}">${E(a.resume||'Download')}</a>`:'—'}<br>Additional info: ${E(a.info||'—')}</div>
 <div class="fg"><label>Change applied program</label>${sel('p',progOpts(),a.program).replace('<select','<select onchange="A.appProg(\''+a.id+'\',this.value)"')}</div>
 <div class="row"><button class="btn btn-o" onclick="FS.closeModal()">Close</button></div>`)};
A.appProg=async(id,v)=>{FS.state.applications.find(x=>x.id===id).program=v;await commit('Program updated')};

const stuFilter=()=>(FS.ui.sq||'').toLowerCase();
function aStudents(){const tab=FS.ui.stab||'apps',S=FS.state,f=FS.ui.sf||'All';
 const tabs=A.tabs('stab',[['apps','Applications ('+S.applications.length+')'],['students','Students ('+S.students.length+')']],tab);
 if(tab==='apps'){const list=S.applications.filter(a=>f==='All'||a.status===f).slice().reverse();
  return tabs+`<div class="pill-row" style="margin-bottom:14px">${['All','Pending','Under Review','Approved','Rejected'].map(x=>`<button class="${f===x?'on':''}" onclick="A.set('sf','${x}')">${x}</button>`).join('')}</div><div class="card tw"><table class="tbl"><tr><th>ID</th><th>Applicant</th><th>Program</th><th>College</th><th>Date</th><th>Status</th><th>Actions</th></tr>${list.map(a=>`<tr><td>${E(a.id)}</td><td><b>${E(a.name)}</b><br><span class="hint">${E(a.email)}</span></td><td>${E(FS.pname(a.program))}</td><td>${E(a.college)}<br><span class="hint">${E(a.qualification)} · ${E(a.year)}</span></td><td>${FS.fmt(a.date)}</td><td><span class="tag ${a.status==='Approved'?'g':a.status==='Rejected'?'r':'a'}">${a.status}</span></td><td><div class="row" style="gap:6px"><button class="btn btn-o btn-sm" onclick="A.appView('${a.id}')">Details</button>${['Pending','Under Review'].includes(a.status)?`${a.status==='Pending'?`<button class="btn btn-o btn-sm" onclick="A.review('${a.id}')">Review</button>`:''}<button class="btn btn-g btn-sm" onclick="A.approve('${a.id}')">Approve</button><button class="btn btn-d btn-sm" onclick="A.reject('${a.id}')">Reject</button>`:''}${delBtn(`A.appDel('${a.id}')`,'✕')}</div></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No applications</td></tr>'}</table></div>`}
 const q=stuFilter(),list=S.students.filter(s=>!q||(s.name+s.email+s.id+FS.pname(s.program)).toLowerCase().includes(q));
 return tabs+`<div class="row sp-b" style="margin-bottom:14px"><input style="max-width:320px" placeholder="🔍 Search students…" value="${E(FS.ui.sq||'')}" oninput="FS.ui.sq=this.value;FS.render(true);var i=document.querySelector('.pbody input');i.focus();i.setSelectionRange(99,99)"><div class="row"><button class="btn btn-o btn-sm" onclick="A.csv()">⬇ Export CSV</button><button class="btn btn-p btn-sm" onclick="A.stuForm()">+ Add student</button></div></div><div class="card tw"><table class="tbl"><tr><th>ID</th><th>Student</th><th>Program</th><th>Progress</th><th>Attendance</th><th>Avg score</th><th>Fee</th><th>Status</th><th></th></tr>${list.map(s=>`<tr><td>${E(s.id)}</td><td><b>${E(s.name)}</b><br><span class="hint">${E(s.email)}</span></td><td>${E(FS.pname(s.program))}</td><td style="min-width:120px">${FS.progressOf(s)}%${FS.bar(FS.progressOf(s))}</td><td>${s.attendance}%</td><td>${FS.scoreOf(s)}%</td><td><span class="tag ${s.feeStatus==='Paid'?'g':'a'}">${E(s.feeStatus||'Pending')}</span></td><td><span class="tag ${s.status==='Active'?'g':'r'}">${E(s.status)}</span></td><td><button class="btn btn-o btn-sm" onclick="A.student('${s.id}')">Manage</button></td></tr>`).join('')||'<tr><td colspan="9" class="empty">No students</td></tr>'}</table></div>`}
A.stuForm=()=>FS.modal(`<h3>Add student</h3><form onsubmit="return A.stuCreate(event)"><div class="frow"><div class="fg"><label>Full name *</label><input name="name" required></div><div class="fg"><label>Email *</label><input name="email" type="email" required></div></div>
 <div class="frow"><div class="fg"><label>Program *</label>${sel('program',progOpts(),'')}</div><div class="fg"><label>Temporary password * (min 8)</label><input name="password" minlength="8" required></div></div>
 <div class="frow"><div class="fg"><label>City</label><input name="city"></div><div class="fg"><label>College</label><input name="college"></div></div>
 <div class="frow"><div class="fg"><label>Phone</label><input name="phone"></div><div class="fg"><label>Fee status</label>${sel('feeStatus',[['Pending','Pending'],['Paid','Paid']],'Pending')}</div></div>
 <div class="row"><button class="btn btn-p">Create student</button><button type="button" class="btn btn-o" onclick="FS.closeModal()">Cancel</button></div></form>`);
A.stuCreate=async(e,)=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target).entries());await call('POST','/api/admin/students',f,'Student created');return false};
A.student=id=>{const s=FS.state.students.find(x=>x.id===id),el=FS.eligible(s);
 FS.modal(`<h3>${E(s.name)} <span class="hint" style="font-weight:400">${E(s.id)}</span></h3><p>${E(s.email)} · ${E(s.city||'—')} · ${E(s.college||'—')}</p>
 <div class="grid g3" style="margin:14px 0"><div class="card flat stat"><div><b>${FS.progressOf(s)}%</b><span>Progress</span></div></div><div class="card flat stat"><div><b>${s.attendance}%</b><span>Attendance</span></div></div><div class="card flat stat"><div><b>${FS.scoreOf(s)}%</b><span>Avg score</span></div></div></div>
 <p style="margin-bottom:12px">Certificate eligibility: <span class="tag ${el.ok?'g':'a'}">${el.ok?'Eligible':'Not yet'}</span>${s.resumeId?` · <a href="${FS.fileUrl(s.resumeId,1)}">Resume</a>`:''}</p>
 <form onsubmit="return A.saveStudent(event,'${s.id}')"><div class="frow"><div class="fg"><label>Name</label><input name="name" required value="${E(s.name)}"></div><div class="fg"><label>Phone</label><input name="phone" value="${E(s.phone||'')}"></div></div>
 <div class="frow"><div class="fg"><label>City</label><input name="city" value="${E(s.city||'')}"></div><div class="fg"><label>College</label><input name="college" value="${E(s.college||'')}"></div></div>
 <div class="frow"><div class="fg"><label>Assigned program</label>${sel('program',progOpts(),s.program)}</div><div class="fg"><label>Account status</label>${sel('status',[['Active','Active'],['Suspended','Suspended']],s.status)}</div></div>
 <div class="frow"><div class="fg"><label>Fee status</label>${sel('feeStatus',[['Pending','Pending'],['Paid','Paid']],s.feeStatus||'Pending')}</div><div class="fg"><label>Payment reference</label><input name="feeRef" value="${E(s.feeRef||'')}"></div></div>
 <div class="frow"><div class="fg"><label>Attendance (%)</label><input name="attendance" type="number" min="0" max="100" value="${s.attendance}"></div><div class="fg"><label>Reset password (optional, min 8)</label><input name="pw" minlength="8" placeholder="Leave blank to keep"></div></div>
 <div class="row"><button class="btn btn-p">Save changes</button><button type="button" class="btn btn-o" onclick="FS.closeModal()">Close</button><span style="flex:1"></span>${delBtn(`A.stuDel('${s.id}')`,'Delete student')}</div></form>`)};
A.saveStudent=async(e,id)=>{e.preventDefault();const f=e.target,s=FS.state.students.find(x=>x.id===id);
 Object.assign(s,{name:f.name.value,phone:f.phone.value,city:f.city.value,college:f.college.value,program:f.program.value,status:f.status.value,feeStatus:f.feeStatus.value,feeRef:f.feeRef.value,attendance:+f.attendance.value});
 const pw=f.pw.value;await FS.save();
 if(pw){try{await FS.api('PUT','/api/admin/students/'+id+'/account',{password:pw})}catch(x){FS.err(x);return false}}
 FS.toast('Student updated');FS.render(true);return false};
A.stuDel=async id=>{if(!confirm('Delete this student, their login and all their submissions, results and applications? Issued certificates are kept. This cannot be undone.'))return;await call('DELETE','/api/admin/students/'+id,undefined,'Student deleted')};

/* ================= Programs ================= */
function aPrograms(){return `<div class="ch-h"><span class="hint">Create, edit, publish or remove programs. Unpublished programs are hidden from the public site and students.</span><button class="btn btn-p" onclick="A.progForm()">+ Create program</button></div>
 <div class="card tw"><table class="tbl"><tr><th>Program</th><th>Category</th><th>Duration</th><th>Mode</th><th>Mentor</th><th>Modules</th><th>Enrolled</th><th>Status</th><th></th></tr>${FS.programs().map(p=>`<tr><td><b>${E(p.icon)} ${E(p.name)}</b></td><td>${E(p.cat)}</td><td>${p.months} mo</td><td>${E(p.mode)}</td><td>${E(FS.mentorOf(p.id))}</td><td>${(p.modules||[]).length}</td><td>${FS.state.students.filter(s=>s.program===p.id).length}</td><td><span class="tag ${p.published===false?'r':'g'}">${p.published===false?'Hidden':'Published'}</span></td><td><div class="row" style="gap:6px"><button class="btn btn-o btn-sm" onclick="A.progForm('${p.id}')">Edit</button><button class="btn btn-o btn-sm" onclick="FS.ui.cpid='${p.id}';FS.go('#/admin/content')">Content</button><button class="btn btn-o btn-sm" onclick="A.progToggle('${p.id}')">${p.published===false?'Publish':'Hide'}</button>${delBtn(`A.progDel('${p.id}')`)}</div></td></tr>`).join('')}</table></div>`}
A.progToggle=async id=>{const p=FS.program(id);p.published=p.published===false;await commit(p.published?'Published':'Hidden')};
A.progDel=async id=>{const p=FS.program(id),n=FS.state.students.filter(s=>s.program===id).length;
 if(n){FS.toast(`${n} student(s) are enrolled. Move them to another program or hide this program instead.`);return}
 if(!confirm(`Delete "${p.name}" and all its modules, videos, files, assignments and questions? This cannot be undone.`))return;
 FS.state.programs=FS.state.programs.filter(x=>x.id!==id);await commit('Program deleted')};
A.progForm=id=>{const p=id?FS.program(id):{name:'',icon:'🎓',color:'#f3ecd9',short:'',overview:'',live:'',months:3,mode:'Online',cat:'Technology',partner:'finsang',mentor:'',published:true,order:FS.programs().length,skills:[],careers:[],topics:[],outcomes:[],assess:[],eligibility:[],links:[],faqs:[],roadmap:[]};
 FS.modal(`<h3>${id?'Edit':'Create'} program</h3><form onsubmit="return A.saveProg(event,'${id||''}')">
 <div class="frow"><div class="fg"><label>Name *</label><input name="name" required value="${E(p.name)}"></div><div class="fg"><label>Icon (emoji)</label><input name="icon" maxlength="4" value="${E(p.icon)}"></div></div>
 <div class="fg"><label>Short description *</label><textarea name="short" required>${E(p.short)}</textarea></div>
 <div class="frow"><div class="fg"><label>Duration (months)</label><input name="months" type="number" min="1" max="24" value="${p.months}"></div><div class="fg"><label>Mode</label>${sel('mode',['Online','Hybrid','Classroom'].map(x=>[x,x]),p.mode)}</div></div>
 <div class="frow"><div class="fg"><label>Category</label><input name="cat" value="${E(p.cat)}"></div><div class="fg"><label>Assigned mentor (display name)</label><input name="mentor" value="${E(p.mentor||'')}"></div></div>
 <div class="frow"><div class="fg"><label>Industry partner</label>${sel('partner',Object.keys(FS.ORGS).map(k=>[k,FS.ORGS[k].short]),p.partner)}</div><div class="fg"><label>Card colour</label><input name="color" type="color" style="height:44px;padding:4px" value="${E(/^#[0-9a-f]{6}$/i.test(p.color)?p.color:'#f3ecd9')}"></div></div>
 <div class="frow"><div class="fg"><label>Display order</label><input name="order" type="number" value="${p.order||0}"></div><div class="fg"><label>Visibility</label>${sel('published',[['1','Published'],['0','Hidden']],p.published===false?'0':'1')}</div></div>
 <div class="fg"><label>Overview</label><textarea name="overview" rows="3">${E(p.overview||'')}</textarea></div>
 <div class="fg"><label>Live project description</label><textarea name="live" rows="3">${E(p.live||'')}</textarea></div>
 <div class="frow"><div class="fg"><label>Key skills</label>${ta('skills',p.skills)}</div><div class="fg"><label>Career opportunities</label>${ta('careers',p.careers)}</div></div>
 <div class="frow"><div class="fg"><label>Topics covered</label>${ta('topics',p.topics)}</div><div class="fg"><label>Learning outcomes</label>${ta('outcomes',p.outcomes)}</div></div>
 <div class="frow"><div class="fg"><label>Assessment methodology</label>${ta('assess',p.assess)}</div><div class="fg"><label>Eligibility</label>${ta('eligibility',p.eligibility)}</div></div>
 <div class="fg"><label>Roadmap (one month per block; separate months with a blank line)</label><textarea name="roadmap" rows="6">${E((p.roadmap||[]).map(m=>m.join('\n')).join('\n\n'))}</textarea></div>
 <div class="frow"><div class="fg"><label>External resources (Title | https://url)</label>${ta('links',(p.links||[]).map(l=>l[0]+' | '+l[1]),'MDN Web Docs | https://developer.mozilla.org')}</div><div class="fg"><label>FAQs (Question | Answer)</label>${ta('faqs',(p.faqs||[]).map(l=>l[0]+' | '+l[1]),'Question | Answer')}</div></div>
 <div class="row"><button class="btn btn-p">Save program</button><button type="button" class="btn btn-o" onclick="FS.closeModal()">Cancel</button></div></form>`,true)};
A.saveProg=async(e,id)=>{e.preventDefault();const f=e.target;
 const pair=v=>lines(v).map(l=>{const i=l.indexOf('|');return i<0?[l,'']:[l.slice(0,i).trim(),l.slice(i+1).trim()]});
 const v={name:f.name.value.trim(),icon:f.icon.value||'🎓',short:f.short.value,months:+f.months.value||3,mode:f.mode.value,cat:f.cat.value,mentor:f.mentor.value.trim(),partner:f.partner.value,color:f.color.value,order:+f.order.value||0,published:f.published.value==='1',overview:f.overview.value,live:f.live.value,
  skills:lines(f.skills.value),careers:lines(f.careers.value),topics:lines(f.topics.value),outcomes:lines(f.outcomes.value),assess:lines(f.assess.value),eligibility:lines(f.eligibility.value),
  roadmap:f.roadmap.value.split(/\n\s*\n/).map(lines).filter(m=>m.length),links:pair(f.links.value),faqs:pair(f.faqs.value).filter(x=>x[1])};
 if(id)Object.assign(FS.program(id),v);
 else{let nid=v.name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');if(nid.length<2)nid='program-'+Date.now().toString(36);while(FS.program(nid))nid+='-2';
  FS.state.programs.push({id:nid,...v,modules:[{id:nid+'-M0',title:'Module 1: Getting Started',videos:[],docs:[]}],assignments:[],quiz:[],papers:[]})}
 FS.closeModal();await commit('Program saved');return false};

/* ================= Content (shared with trainer) ================= */
const modOpts=pid=>(FS.program(pid).modules||[]).map(m=>[m.id,m.title]);
FS.contentPanel=(pid)=>{const p=FS.program(pid);if(!p)return '<div class="empty card">No program selected.</div>';const as=p.assignments||[];
 return `<div class="row" style="margin-bottom:16px"><button class="btn btn-p btn-sm" onclick="A.cform('doc','${pid}')">⬆ Add material</button><button class="btn btn-p btn-sm" onclick="A.cform('video','${pid}')">▶ Add video</button><button class="btn btn-o btn-sm" onclick="A.cform('assign','${pid}')">📤 Publish assignment</button><button class="btn btn-o btn-sm" onclick="A.cform('paper','${pid}')">📄 Add paper</button><button class="btn btn-o btn-sm" onclick="A.cform('quiz','${pid}')">❓ Add MCQ</button><button class="btn btn-o btn-sm" onclick="A.cform('module','${pid}')">+ Module</button></div>
 ${(p.modules||[]).map((m,i)=>`<div class="mod"><div class="mh"><span>Module ${i+1}: ${E(m.title)}</span><span class="row" style="gap:6px"><span class="tag m">${m.videos.length} videos · ${m.docs.length} files</span><button class="btn btn-o btn-sm" onclick="A.cform('module','${pid}','${m.id}')">Rename</button><button class="btn btn-o btn-sm" ${i?'':'disabled'} onclick="A.cmove('${pid}','${m.id}',-1)">↑</button><button class="btn btn-o btn-sm" ${i<p.modules.length-1?'':'disabled'} onclick="A.cmove('${pid}','${m.id}',1)">↓</button>${delBtn(`A.cdel('module','${pid}','${m.id}')`,'✕')}</span></div><div class="mb">${m.videos.map(v=>`<div class="file"><div class="fi LINK">VID</div><div style="flex:1">${E(v.title)}${v.url?'':' <span class="hint">(no link yet)</span>'}</div><span class="hint">${v.dur} min</span><button class="btn btn-o btn-sm" onclick="A.cform('video','${pid}','${v.id}')">Edit</button>${delBtn(`A.cdel('video','${pid}','${v.id}')`,'✕')}</div>`).join('')}${m.docs.map(d=>`<div class="file"><div class="fi ${E(d.type)}">${E(d.type)}</div><div style="flex:1">${E(d.title)}${d.fileId||d.url?'':' <span class="hint">(no file yet)</span>'}</div>${d.fileId?`<a class="btn btn-o btn-sm" href="${FS.fileUrl(d.fileId,1)}">⬇</a>`:''}<button class="btn btn-o btn-sm" onclick="A.cform('doc','${pid}','${d.id}')">Edit</button>${delBtn(`A.cdel('doc','${pid}','${d.id}')`,'✕')}</div>`).join('')}</div></div>`).join('')}
 <div class="grid g2"><div class="card"><h3 style="margin-bottom:8px">Assignments (${as.length})</h3>${as.map(a=>`<div class="li"><div style="flex:1"><b>${E(a.title)}</b><br><span class="hint">Due ${FS.fmt(a.due)} · ${a.marks} marks</span></div><button class="btn btn-o btn-sm" onclick="A.cform('assign','${pid}','${a.id}')">Edit</button>${delBtn(`A.cdel('assign','${pid}','${a.id}')`,'✕')}</div>`).join('')||'<div class="empty">None</div>'}</div>
 <div class="card"><h3 style="margin-bottom:8px">Assessments</h3><p style="font-size:.9rem">${(p.quiz||[]).length} MCQs in question bank · ${(p.papers||[]).length} sample/previous/mock papers</p><p class="hint" style="margin-top:8px">Manage individual questions and papers under Assessments.</p></div></div>`};
function aContent(){const pid=FS.programs().find(p=>p.id===FS.ui.cpid)?FS.ui.cpid:(FS.programs()[0]||{}).id;if(!pid)return '<div class="empty card">Create a program first.</div>';
 return `<div class="row" style="margin-bottom:16px"><label style="margin:0">Program</label><select style="max-width:320px" onchange="A.set('cpid',this.value)">${progOpts().map(o=>`<option value="${E(o[0])}" ${o[0]===pid?'selected':''}>${E(o[1])}</option>`).join('')}</select></div>${FS.contentPanel(pid)}`}
const fileField=(label,existing)=>`<div class="fg"><label>${label}</label><input type="file" name="file">${existing?`<span class="hint">Current file kept unless you choose a new one. <a href="${FS.fileUrl(existing,1)}">Download current</a></span>`:'<span class="hint">PDF, Office, ZIP, images or MP4 up to 25 MB.</span>'}</div>`;
A.cform=(kind,pid,iid)=>{const p=FS.program(pid),mods=modOpts(pid);let h='',x={};
 const find=(arr)=>iid?(arr||[]).find(i=>i.id===iid)||{}:{};
 if(kind==='module'){x=find(p.modules);h=`<h3>${iid?'Rename':'Add'} module</h3><div class="fg"><label>Module title</label><input name="title" required value="${E(x.title||'')}"></div>`}
 if(kind==='doc'){x=find((p.modules||[]).flatMap(m=>m.docs));const cm=(p.modules||[]).find(m=>m.docs.some(d=>d.id===iid));h=`<h3>${iid?'Edit':'Add'} study material</h3><div class="fg"><label>Title</label><input name="title" required value="${E(x.title||'')}"></div><div class="frow"><div class="fg"><label>Type</label>${sel('type',['PDF','PPT','DOC','ZIP','LINK'].map(t=>[t,t]),x.type||'PDF')}</div><div class="fg"><label>Module</label>${sel('mid',mods,cm?cm.id:mods[0]&&mods[0][0])}</div></div>${fileField('File',x.fileId)}<div class="fg"><label>…or external link (optional)</label><input name="url" type="url" placeholder="https://" value="${E(x.url||'')}"></div>`}
 if(kind==='video'){x=find((p.modules||[]).flatMap(m=>m.videos));const cm=(p.modules||[]).find(m=>m.videos.some(d=>d.id===iid));h=`<h3>${iid?'Edit':'Add'} video lesson</h3><div class="fg"><label>Title</label><input name="title" required value="${E(x.title||'')}"></div><div class="fg"><label>Video URL (YouTube, Vimeo or direct .mp4)</label><input name="url" type="url" placeholder="https://www.youtube.com/watch?v=…" value="${E(x.url||'')}"></div><div class="frow"><div class="fg"><label>Duration (min)</label><input name="dur" type="number" min="1" value="${x.dur||10}"></div><div class="fg"><label>Module</label>${sel('mid',mods,cm?cm.id:mods[0]&&mods[0][0])}</div></div><div class="fg"><label>Description</label><textarea name="desc">${E(x.desc||'')}</textarea></div>`}
 if(kind==='assign'){x=find(p.assignments);h=`<h3>${iid?'Edit':'Publish'} assignment</h3><div class="fg"><label>Title</label><input name="title" required value="${E(x.title||'')}"></div><div class="fg"><label>Instructions</label><textarea name="desc" required>${E(x.desc||'')}</textarea></div><div class="frow"><div class="fg"><label>Deadline</label><input type="date" name="due" required value="${E(x.due||FS.day(14))}"></div><div class="fg"><label>Max marks</label><input type="number" name="marks" value="${x.marks||25}" min="1"></div></div>${fileField('Reference file (optional)',x.fileId)}`}
 if(kind==='paper'){x=find(p.papers);h=`<h3>${iid?'Edit':'Add'} paper</h3><div class="fg"><label>Title</label><input name="title" required value="${E(x.title||'')}"></div><div class="frow"><div class="fg"><label>Type</label>${sel('type',['Sample Paper','Previous Paper','Mock Test'].map(t=>[t,t]),x.type||'Sample Paper')}</div><div class="fg"><label>Questions</label><input name="q" type="number" min="1" value="${x.q||25}"></div></div><div class="fg"><label>Duration (min)</label><input name="mins" type="number" min="1" value="${x.mins||45}"></div>${fileField('PDF (optional)',x.fileId)}`}
 if(kind==='quiz'){x=find(p.quiz);h=`<h3>${iid?'Edit':'Add'} MCQ</h3><div class="fg"><label>Question</label><textarea name="q" required>${E(x.q||'')}</textarea></div>${[0,1,2,3].map(i=>`<div class="fg"><label>Option ${'ABCD'[i]}</label><input name="o${i}" required value="${E((x.opts||[])[i]||'')}"></div>`).join('')}<div class="frow"><div class="fg"><label>Correct answer</label>${sel('a',['A','B','C','D'].map((l,i)=>[String(i),l]),String(x.a||0))}</div><div class="fg"><label>Topic / module</label>${sel('mid',mods,x.mid||mods[0]&&mods[0][0])}</div></div>`}
 FS.modal(`<form onsubmit="return A.csave(event,'${kind}','${pid}','${iid||''}')">${h}<div class="row"><button class="btn btn-p">${iid?'Save':'Publish'}</button><button type="button" class="btn btn-o" onclick="FS.closeModal()">Cancel</button></div></form>`)};
A.csave=async(e,k,pid,iid)=>{e.preventDefault();const f=e.target,p=FS.program(pid),btn=f.querySelector('.btn-p');btn.disabled=true;
 try{
  let up=null;const file=f.file&&f.file.files[0];if(file){if(file.size>25*1024*1024)throw new Error('File must be under 25 MB');up=await FS.upload(file,'material')}
  const upsert=(arr,rec)=>{const i=arr.findIndex(x=>x.id===rec.id);if(i<0)arr.push(rec);else arr[i]=rec};
  if(k==='module'){if(iid)p.modules.find(m=>m.id===iid).title=f.title.value;else p.modules.push({id:FS.uid('M'),title:f.title.value,videos:[],docs:[]})}
  if(k==='doc'||k==='video'){
   let old=null;p.modules.forEach(m=>{const l=m[k==='doc'?'docs':'videos'],i=l.findIndex(x=>x.id===iid);if(i>=0){old=l[i];l.splice(i,1)}});
   const rec=k==='doc'?{id:iid||FS.uid('D'),title:f.title.value,type:f.type.value,fileId:up?up.id:(old?old.fileId:''),url:f.url.value}:{id:iid||FS.uid('V'),title:f.title.value,url:f.url.value,dur:+f.dur.value||10,desc:f.desc.value};
   (p.modules.find(m=>m.id===f.mid.value)||p.modules[0])[k==='doc'?'docs':'videos'].push(rec)}
  if(k==='assign'){const old=(p.assignments||[]).find(a=>a.id===iid)||{};upsert(p.assignments,{id:iid||FS.uid('A'),title:f.title.value,desc:f.desc.value,due:f.due.value,marks:+f.marks.value||25,fileId:up?up.id:(old.fileId||'')});
   if(!iid&&FS.state.announcements&&FS.user().role==='admin')FS.state.announcements.unshift({id:FS.uid('N'),type:'Deadline',title:'New assignment: '+f.title.value,body:'Due '+FS.fmt(f.due.value)+'.',date:FS.day(0),prog:pid,by:'admin'})}
  if(k==='paper'){const old=(p.papers||[]).find(a=>a.id===iid)||{};upsert(p.papers,{id:iid||FS.uid('P'),title:f.title.value,type:f.type.value,q:+f.q.value||20,mins:+f.mins.value||30,fileId:up?up.id:(old.fileId||'')})}
  if(k==='quiz')upsert(p.quiz,{id:iid||FS.uid('Q'),mid:f.mid.value,q:f.q.value,opts:[0,1,2,3].map(i=>f['o'+i].value),a:+f.a.value});
  FS.closeModal();await commit('Saved ✓');
 }catch(x){FS.err(x);btn.disabled=false}
 return false};
A.cdel=async(kind,pid,id)=>{const p=FS.program(pid);
 if(!confirm(kind==='module'?'Delete this module and all its videos and files?':'Delete this item?'))return;
 if(kind==='module')p.modules=p.modules.filter(m=>m.id!==id);
 if(kind==='video')p.modules.forEach(m=>m.videos=m.videos.filter(v=>v.id!==id));
 if(kind==='doc')p.modules.forEach(m=>m.docs=m.docs.filter(v=>v.id!==id));
 if(kind==='assign')p.assignments=p.assignments.filter(a=>a.id!==id);
 if(kind==='paper')p.papers=p.papers.filter(a=>a.id!==id);
 if(kind==='quiz')p.quiz=p.quiz.filter(a=>a.id!==id);
 await commit('Deleted')};
A.cmove=async(pid,id,d)=>{const m=FS.program(pid).modules,i=m.findIndex(x=>x.id===id),j=i+d;if(j<0||j>=m.length)return;[m[i],m[j]]=[m[j],m[i]];await commit()};

/* ================= Assessments (evaluation helpers are shared with trainers) ================= */
FS.evalModal=id=>{const s=FS.state.submissions.find(x=>x.id===id),a=FS.assignments(s.pid).find(x=>x.id===s.aid)||{marks:100,title:s.title};
 FS.modal(`<h3>Evaluate: ${E(a.title)}</h3><p><b>${E(s.name)}</b> · submitted ${FS.fmt(s.date)}</p><div class="card flat" style="margin:10px 0">${s.link?`Link: <a href="${E(s.link)}" target="_blank" rel="noopener noreferrer">${E(s.link)}</a><br>`:''}${s.file?`File: ${s.fileId?`<a href="${FS.fileUrl(s.fileId,1)}">${E(s.file)}</a>`:E(s.file)}<br>`:''}Note: ${E(s.note)}</div>
 <form onsubmit="return A.evalSave(event,'${id}')"><div class="frow"><div class="fg"><label>Marks (max ${a.marks})</label><input name="m" type="number" min="0" max="${a.marks}" required value="${s.marks==null?'':s.marks}"></div></div><div class="fg"><label>Feedback to student</label><textarea name="fb" required>${E(s.feedback)}</textarea></div><div class="row"><button class="btn btn-p">Save evaluation</button><button type="button" class="btn btn-o" onclick="FS.closeModal()">Cancel</button></div></form>`)};
A.evalSave=async(e,id)=>{e.preventDefault();const s=FS.state.submissions.find(x=>x.id===id);s.marks=+e.target.m.value;s.feedback=e.target.fb.value;s.status='Evaluated';FS.closeModal();await commit('Evaluation saved');return false};
FS.subTable=(subs)=>`<div class="card tw"><table class="tbl"><tr><th>Student</th><th>Assignment</th><th>Submitted</th><th>Status</th><th>Marks</th><th></th></tr>${subs.map(s=>`<tr><td><b>${E(s.name)}</b></td><td>${E(s.title)}</td><td>${FS.fmt(s.date)}</td><td>${stTag(s.status)}</td><td>${s.marks==null?'—':s.marks}</td><td><button class="btn btn-${s.status==='Submitted'?'p':'o'} btn-sm" onclick="FS.evalModal('${s.id}')">${s.status==='Submitted'?'Evaluate':'Edit'}</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No submissions</td></tr>'}</table></div>`;
FS.perfTable=(studs)=>`<div class="card tw"><table class="tbl"><tr><th>Student</th><th>Program</th><th>Progress</th><th>Avg score</th><th>Tests taken</th></tr>${studs.map(s=>`<tr><td><b>${E(s.name)}</b></td><td>${E(FS.pname(s.program))}</td><td>${FS.progressOf(s)}%</td><td>${FS.scoreOf(s)}%</td><td>${FS.state.results.filter(r=>r.email===s.email).length}</td></tr>`).join('')}</table></div>`;
function aAssess(){const tab=FS.ui.xtab||'eval',S=FS.state;
 const tabs=A.tabs('xtab',[['eval','Evaluate Submissions'],['bank','Exams & MCQs'],['perf','Student Performance'],['crit','Completion Criteria']],tab);
 if(tab==='eval')return tabs+FS.subTable(S.submissions.slice().reverse());
 if(tab==='perf')return tabs+FS.perfTable(S.students);
 if(tab==='crit')return tabs+critCard();
 const pid=FS.programs().find(p=>p.id===FS.ui.cpid)?FS.ui.cpid:(FS.programs()[0]||{}).id;if(!pid)return tabs+'<div class="empty card">No programs.</div>';
 const p=FS.program(pid);
 return tabs+`<div class="row" style="margin-bottom:16px"><select style="max-width:320px" onchange="A.set('cpid',this.value)">${progOpts().map(o=>`<option value="${E(o[0])}" ${o[0]===pid?'selected':''}>${E(o[1])}</option>`).join('')}</select><button class="btn btn-p btn-sm" onclick="A.cform('quiz','${pid}')">+ Add MCQ</button><button class="btn btn-o btn-sm" onclick="A.cform('paper','${pid}')">+ Create exam / paper</button></div>
 <div class="card"><h3 style="margin-bottom:8px">Question bank (${FS.questions(pid).length})</h3>${FS.questions(pid).map((q,i)=>`<div class="li"><span class="dot"></span><div style="flex:1"><b>${i+1}. ${E(q.q)}</b><br><span class="hint">${E(q.topic)} · Answer: ${E(q.opts[q.a])}</span></div><button class="btn btn-o btn-sm" onclick="A.cform('quiz','${pid}','${q.id}')">Edit</button>${delBtn(`A.cdel('quiz','${pid}','${q.id}')`,'✕')}</div>`).join('')||'<div class="empty">No questions yet</div>'}</div>
 <div class="card" style="margin-top:18px"><h3 style="margin-bottom:8px">Exams & papers</h3>${(p.papers||[]).map(x=>`<div class="li"><div style="flex:1"><b>${E(x.title)}</b><br><span class="hint">${E(x.type)} · ${x.q} Q · ${x.mins} min${x.fileId?' · PDF attached':''}</span></div><button class="btn btn-o btn-sm" onclick="A.cform('paper','${pid}','${x.id}')">Edit</button>${delBtn(`A.cdel('paper','${pid}','${x.id}')`,'✕')}</div>`).join('')||'<div class="empty">None</div>'}</div>`}
const critCard=()=>{const c=FS.state.criteria;return `<div class="card" style="max-width:520px"><h3>Completion & certification criteria</h3><p style="margin:6px 0 14px">Students must meet all three to be certificate-eligible.</p><form onsubmit="return A.crit(event)">${[['progress','Minimum program completion (%)'],['score','Minimum average assessment score (%)'],['attendance','Minimum attendance (%)']].map(x=>`<div class="fg"><label>${x[1]}</label><input name="${x[0]}" type="number" min="0" max="100" value="${c[x[0]]}"></div>`).join('')}<button class="btn btn-p">Save criteria</button></form></div>`};
A.crit=async e=>{e.preventDefault();const f=e.target;FS.state.criteria={id:'criteria',progress:+f.progress.value,score:+f.score.value,attendance:+f.attendance.value};await FS.save();FS.toast('Criteria updated');return false};

/* ================= Certificates ================= */
A.genCert=async(sid)=>{const s=FS.state.students.find(x=>x.id===sid),el=FS.eligible(s);
 if(!el.ok&&!confirm('This student does not meet the criteria. Issue the certificate anyway (admin override)?'))return;
 if(FS.certOf(s.email)){FS.toast('Already issued');return}
 await call('POST','/api/admin/certs',{email:s.email,score:Math.max(FS.scoreOf(s),0)},'Certificate generated with unique ID')};
A.showCert=id=>FS.printCert(FS.state.certs.find(c=>c.id===id));
A.revoke=async id=>{if(!confirm('Revoke this certificate? It will no longer verify.'))return;FS.state.certs=FS.state.certs.filter(c=>c.id!==id);await commit('Certificate revoked')};
function aCerts(){const tab=FS.ui.ctab||'elig',S=FS.state;const tabs=A.tabs('ctab',[['elig','Eligible Students'],['issued','Issued ('+S.certs.length+')'],['verify','Verify']],tab);
 if(tab==='issued')return tabs+`<div class="card tw"><table class="tbl"><tr><th>Certificate ID</th><th>Student</th><th>Program</th><th>Issued</th><th>Score</th><th></th></tr>${S.certs.map(c=>`<tr><td><b>${E(c.id)}</b>${c.demo?' <span class="demo-b">SAMPLE</span>':''}</td><td>${E(c.name)}</td><td>${E(FS.pname(c.pid))}</td><td>${FS.fmt(c.date)}</td><td>${c.score}%</td><td><div class="row" style="gap:6px"><button class="btn btn-o btn-sm" onclick="A.showCert('${c.id}')">View / Download</button>${delBtn(`A.revoke('${c.id}')`,'Revoke')}</div></td></tr>`).join('')||'<tr><td colspan="6" class="empty">None issued</td></tr>'}</table></div>`;
 if(tab==='verify')return tabs+`<div class="card" style="max-width:520px"><h3>Verify certificate</h3><form class="row" style="margin-top:10px" onsubmit="return A.adminVerify(event)"><input name="id" placeholder="FSC-2026-0001" style="flex:1" required><button class="btn btn-p">Verify</button></form><div id="vres" style="margin-top:12px"></div></div>`;
 return tabs+`<div class="card tw"><table class="tbl"><tr><th>Student</th><th>Program</th><th>Progress</th><th>Score</th><th>Attendance</th><th>Eligibility</th><th></th></tr>${S.students.map(s=>{const el=FS.eligible(s),c=FS.certOf(s.email),rq=S.certReq.includes(s.email);return `<tr><td><b>${E(s.name)}</b>${rq?' <span class="tag a">Requested</span>':''}</td><td>${E(FS.pname(s.program))}</td><td>${el.p}%</td><td>${el.sc}%</td><td>${s.attendance}%</td><td><span class="tag ${el.ok?'g':'m'}">${el.ok?'Eligible':'Not yet'}</span></td><td>${c?`<span class="tag g">${E(c.id)}</span>`:`<button class="btn ${el.ok?'btn-p':'btn-o'} btn-sm" onclick="A.genCert('${s.id}')">Generate</button>`}</td></tr>`}).join('')}</table></div>`}
A.adminVerify=e=>{e.preventDefault();const c=FS.state.certs.find(x=>x.id===e.target.id.value.trim().toUpperCase());document.getElementById('vres').innerHTML=c?`<div class="alert s">✅ Valid: ${E(c.name)}, ${E(FS.pname(c.pid))}, ${FS.fmt(c.date)}</div>`:`<div class="alert e">❌ Not found</div>`;return false};

/* ================= Placement ================= */
function aPlace(){const tab=FS.ui.ltab||'jobs',S=FS.state;
 const tabs=A.tabs('ltab',[['jobs','Openings ('+S.jobs.length+')'],['apps','Applications ('+S.jobApps.length+')'],['int','Interviews ('+S.interviews.length+')'],['emp','Employers ('+S.employers.length+')']],tab);
 const job=id=>S.jobs.find(j=>j.id===id)||{title:'(removed)',company:''};
 const stuName=email=>(FS.studentRec(email)||{name:email}).name;
 if(tab==='apps')return tabs+`<div class="card tw"><table class="tbl"><tr><th>Student</th><th>Role</th><th>Company</th><th>Applied</th><th>Status</th><th></th></tr>${S.jobApps.map(a=>`<tr><td><b>${E(a.name)}</b></td><td>${E(job(a.jobId).title)}</td><td>${E(job(a.jobId).company)}</td><td>${FS.fmt(a.date)}</td><td><select onchange="A.jobStatus('${a.id}',this.value)">${['Applied','Shortlisted','Interview Scheduled','Selected','Rejected'].map(x=>`<option ${x===a.status?'selected':''}>${x}</option>`).join('')}</select></td><td><div class="row" style="gap:6px"><button class="btn btn-o btn-sm" onclick="A.intForm('${a.id}')">Schedule interview</button>${delBtn(`A.jaDel('${a.id}')`,'✕')}</div></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No applications yet</td></tr>'}</table></div>`;
 if(tab==='int')return tabs+`<div class="card tw"><table class="tbl"><tr><th>Student</th><th>Role</th><th>Date</th><th>Time</th><th>Mode</th><th></th></tr>${S.interviews.map(i=>`<tr><td>${E(stuName(i.email))}</td><td>${E(job(i.jobId).title)}</td><td>${FS.fmt(i.date)}</td><td>${E(i.time)}</td><td>${E(i.mode)}</td><td>${delBtn(`A.intDel('${i.id}')`,'Cancel')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">None scheduled</td></tr>'}</table></div>`;
 if(tab==='emp')return tabs+`<div class="ch-h"><span class="hint">Employer records</span><button class="btn btn-p btn-sm" onclick="A.empForm()">+ Add employer</button></div><div class="card tw"><table class="tbl"><tr><th>Employer</th><th>Open roles</th><th>Contact</th><th>Phone</th><th></th></tr>${S.employers.map(e=>`<tr><td><b>${E(e.name)}</b>${e.notes?`<br><span class="hint">${E(e.notes)}</span>`:''}</td><td>${S.jobs.filter(j=>j.company===e.name).length}</td><td>${e.contact?mailto(e.contact):'—'}</td><td>${E(e.phone||'—')}</td><td><div class="row" style="gap:6px"><button class="btn btn-o btn-sm" onclick="A.empForm('${e.id}')">Edit</button>${delBtn(`A.empDel('${e.id}')`,'✕')}</div></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No employers yet</td></tr>'}</table></div>`;
 return tabs+`<div class="ch-h"><span class="hint">Placement assistance only — no guarantee of employment.</span><button class="btn btn-p btn-sm" onclick="A.jobForm()">+ Publish opening</button></div><div class="card tw"><table class="tbl"><tr><th>Role</th><th>Company</th><th>Type</th><th>Program</th><th>Min score</th><th>Applicants</th><th></th></tr>${S.jobs.map(j=>`<tr><td><b>${E(j.title)}</b></td><td>${E(j.company)}</td><td><span class="tag ${j.type==='Job'?'g':'a'}">${E(j.type)}</span></td><td>${j.prog==='any'?'Any':E(FS.pname(j.prog))}</td><td>${j.min}%</td><td>${S.jobApps.filter(a=>a.jobId===j.id).length}</td><td><div class="row" style="gap:6px"><button class="btn btn-o btn-sm" onclick="A.jobForm('${j.id}')">Edit</button>${delBtn(`A.jobDel('${j.id}')`,'Remove')}</div></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No openings</td></tr>'}</table></div>`}
A.jobStatus=async(id,v)=>{FS.state.jobApps.find(a=>a.id===id).status=v;await FS.save();FS.toast('Status updated')};
A.jaDel=async id=>{if(!confirm('Delete this application?'))return;FS.state.jobApps=FS.state.jobApps.filter(a=>a.id!==id);await commit()};
A.intDel=async id=>{if(!confirm('Cancel this interview?'))return;FS.state.interviews=FS.state.interviews.filter(a=>a.id!==id);await commit('Interview cancelled')};
A.jobDel=async id=>{if(!confirm('Remove this opening? Applications for it will show as removed.'))return;FS.state.jobs=FS.state.jobs.filter(j=>j.id!==id);await commit('Opening removed')};
A.jobForm=id=>{const j=id?FS.state.jobs.find(x=>x.id===id):{title:'',company:'',loc:'',type:'Job',prog:'any',min:60,org:'finsang',desc:'',elig:[]};
 FS.modal(`<h3>${id?'Edit':'Publish'} job / internship</h3><form onsubmit="return A.jobSave(event,'${id||''}')"><div class="fg"><label>Title</label><input name="title" required value="${E(j.title)}"></div><div class="frow"><div class="fg"><label>Company</label><input name="company" required value="${E(j.company)}" list="emps"><datalist id="emps">${FS.state.employers.map(e=>`<option value="${E(e.name)}">`).join('')}</datalist></div><div class="fg"><label>Location</label><input name="loc" required value="${E(j.loc)}"></div></div><div class="frow"><div class="fg"><label>Type</label>${sel('type',[['Job','Job'],['Internship','Internship']],j.type)}</div><div class="fg"><label>Program</label>${sel('prog',[['any','Any program']].concat(progOpts()),j.prog)}</div></div><div class="frow"><div class="fg"><label>Minimum avg score (%)</label><input name="min" type="number" min="0" max="100" value="${j.min}"></div><div class="fg"><label>Organization</label>${sel('org',Object.keys(FS.ORGS).map(k=>[k,FS.ORGS[k].short]),j.org)}</div></div><div class="fg"><label>Description</label><textarea name="desc" required>${E(j.desc)}</textarea></div><div class="fg"><label>Eligibility (one per line)</label><textarea name="elig">${E((j.elig||[]).join('\n'))}</textarea></div><div class="row"><button class="btn btn-p">${id?'Save':'Publish'}</button><button type="button" class="btn btn-o" onclick="FS.closeModal()">Cancel</button></div></form>`)};
A.jobSave=async(e,id)=>{e.preventDefault();const f=e.target;const v={title:f.title.value,company:f.company.value,org:f.org.value,type:f.type.value,loc:f.loc.value,prog:f.prog.value,min:+f.min.value||0,desc:f.desc.value,elig:lines(f.elig.value)};
 if(id)Object.assign(FS.state.jobs.find(x=>x.id===id),v);
 else{FS.state.jobs.push({id:FS.uid('J'),...v});FS.state.announcements.unshift({id:FS.uid('N'),type:'Placement',title:'New opening: '+v.title,body:v.company+' · '+v.type+'. Check eligibility in Placement.',date:FS.day(0),prog:v.prog==='any'?'all':v.prog,by:'admin'})}
 FS.closeModal();await commit('Saved');return false};
A.empForm=id=>{const x=id?FS.state.employers.find(e=>e.id===id):{name:'',contact:'',phone:'',notes:''};
 FS.modal(`<h3>${id?'Edit':'Add'} employer</h3><form onsubmit="return A.empSave(event,'${id||''}')"><div class="fg"><label>Name</label><input name="n" required value="${E(x.name)}"></div><div class="frow"><div class="fg"><label>Contact email</label><input name="c" type="email" value="${E(x.contact)}"></div><div class="fg"><label>Phone</label><input name="p" value="${E(x.phone||'')}"></div></div><div class="fg"><label>Notes</label><textarea name="no">${E(x.notes||'')}</textarea></div><div class="row"><button class="btn btn-p">Save</button><button type="button" class="btn btn-o" onclick="FS.closeModal()">Cancel</button></div></form>`)};
A.empSave=async(e,id)=>{e.preventDefault();const f=e.target,v={name:f.n.value,contact:f.c.value,phone:f.p.value,notes:f.no.value};
 if(id)Object.assign(FS.state.employers.find(x=>x.id===id),v);else FS.state.employers.push({id:FS.uid('E'),...v});FS.closeModal();await commit('Saved');return false};
A.empDel=async id=>{if(!confirm('Delete this employer record?'))return;FS.state.employers=FS.state.employers.filter(x=>x.id!==id);await commit()};
A.intForm=jaId=>{const a=FS.state.jobApps.find(x=>x.id===jaId);
 FS.modal(`<h3>Schedule interview</h3><p class="hint" style="margin-bottom:10px">${E(a.name)} · ${E((FS.state.jobs.find(j=>j.id===a.jobId)||{}).title||'')}</p><form onsubmit="return A.intSave(event,'${jaId}')"><div class="frow"><div class="fg"><label>Date</label><input type="date" name="d" required value="${FS.day(5)}"></div><div class="fg"><label>Time</label><input name="t" value="11:00 AM"></div></div><div class="fg"><label>Mode</label>${sel('m',['Video call','On-site','Phone'].map(x=>[x,x]),'Video call')}</div><div class="row"><button class="btn btn-p">Schedule</button><button type="button" class="btn btn-o" onclick="FS.closeModal()">Cancel</button></div></form>`)};
A.intSave=async(e,jaId)=>{e.preventDefault();const f=e.target,a=FS.state.jobApps.find(x=>x.id===jaId);
 FS.state.interviews.push({id:FS.uid('I'),email:a.email,jobId:a.jobId,date:f.d.value,time:f.t.value,mode:f.m.value});a.status='Interview Scheduled';FS.closeModal();await commit('Interview scheduled');return false};

/* ================= Announcements ================= */
const ANN_TYPES=['Program Update','Class Schedule','Deadline','Examination','Placement'];
function aAnn(){const list=FS.state.announcements.slice().sort((a,b)=>String(b.date).localeCompare(String(a.date)));
 return `<div class="ch-h"><span class="hint">Shown to students on their dashboard and Announcements page.</span><button class="btn btn-p" onclick="A.annForm()">+ New announcement</button></div><div class="card tw"><table class="tbl"><tr><th>Date</th><th>Type</th><th>Title</th><th>Audience</th><th>By</th><th></th></tr>${list.map(a=>`<tr><td>${FS.fmt(a.date)}</td><td><span class="tag m">${E(a.type)}</span></td><td><b>${E(a.title)}</b><br><span class="hint">${E(a.body)}</span></td><td>${a.prog==='all'?'All students':E(FS.pname(a.prog))}</td><td>${E(a.by||'')}</td><td><div class="row" style="gap:6px"><button class="btn btn-o btn-sm" onclick="A.annForm('${a.id}')">Edit</button>${delBtn(`A.annDel('${a.id}')`,'✕')}</div></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No announcements</td></tr>'}</table></div>`}
A.annForm=id=>{const a=id?FS.state.announcements.find(x=>x.id===id):{type:'Program Update',title:'',body:'',prog:'all',date:FS.day(0)};
 FS.modal(`<h3>${id?'Edit':'New'} announcement</h3><form onsubmit="return A.annSave(event,'${id||''}')"><div class="frow"><div class="fg"><label>Type</label>${sel('type',ANN_TYPES.map(x=>[x,x]),a.type)}</div><div class="fg"><label>Audience</label>${sel('prog',[['all','All students']].concat(progOpts()),a.prog)}</div></div><div class="fg"><label>Title</label><input name="title" required value="${E(a.title)}"></div><div class="fg"><label>Message</label><textarea name="body" required rows="4">${E(a.body)}</textarea></div><div class="fg"><label>Date</label><input name="date" type="date" required value="${E(a.date)}"></div><div class="row"><button class="btn btn-p">${id?'Save':'Publish'}</button><button type="button" class="btn btn-o" onclick="FS.closeModal()">Cancel</button></div></form>`)};
A.annSave=async(e,id)=>{e.preventDefault();const f=e.target,v={type:f.type.value,prog:f.prog.value,title:f.title.value,body:f.body.value,date:f.date.value};
 if(id)Object.assign(FS.state.announcements.find(x=>x.id===id),v);else FS.state.announcements.unshift({id:FS.uid('N'),by:'admin',...v});FS.closeModal();await commit('Saved');return false};
A.annDel=async id=>{if(!confirm('Delete this announcement?'))return;FS.state.announcements=FS.state.announcements.filter(x=>x.id!==id);await commit('Deleted')};

/* ================= Trainers & staff accounts ================= */
function aStaff(){return `<div class="ch-h"><span class="hint">Trainers see only their assigned programs. Admins have full access.</span><button class="btn btn-p" onclick="A.staffForm()">+ Add trainer / admin</button></div><div class="card tw"><table class="tbl"><tr><th>Name</th><th>Email</th><th>Role</th><th>Programs</th><th>Created</th><th></th></tr>${FS.state.users.map(u=>`<tr><td><b>${E(u.name)}</b>${u.email===FS.me.email?' <span class="tag t">You</span>':''}</td><td>${E(u.email)}</td><td><span class="tag ${u.role==='admin'?'a':'g'}">${E(u.role)}</span></td><td>${u.role==='admin'?'All':(u.programs||[]).map(id=>E(FS.pname(id))).join(', ')||'<span class="hint">None assigned</span>'}</td><td>${E(String(u.created||'').slice(0,10))}</td><td><div class="row" style="gap:6px"><button class="btn btn-o btn-sm" onclick="A.staffForm(${u.id})">Edit</button>${u.email===FS.me.email?'':delBtn(`A.staffDel(${u.id})`,'✕')}</div></td></tr>`).join('')}</table></div>`}
A.staffForm=id=>{const u=id?FS.state.users.find(x=>x.id===id):{name:'',email:'',role:'trainer',programs:[]};
 FS.modal(`<h3>${id?'Edit':'Add'} staff account</h3><form onsubmit="return A.staffSave(event,${id||0})"><div class="frow"><div class="fg"><label>Full name</label><input name="name" required value="${E(u.name)}"></div><div class="fg"><label>Email</label><input name="email" type="email" required ${id?'disabled':''} value="${E(u.email)}"></div></div>
 <div class="frow"><div class="fg"><label>Role</label>${sel('role',[['trainer','Trainer / mentor'],['admin','Administrator']],u.role).replace('<select','<select '+(id&&u.email===FS.me.email?'disabled':''))}</div><div class="fg"><label>${id?'Reset password (optional)':'Password (min 8)'}</label><input name="password" minlength="8" ${id?'':'required'} autocomplete="new-password"></div></div>
 <div class="fg"><label>Assigned programs (trainers)</label><div class="pill-row">${FS.programs().map(p=>`<label style="font-weight:500;display:flex;gap:6px;align-items:center;margin-right:10px"><input type="checkbox" name="pr" value="${E(p.id)}" style="width:auto" ${(u.programs||[]).includes(p.id)?'checked':''}> ${E(p.name)}</label>`).join('')}</div></div>
 <div class="row"><button class="btn btn-p">${id?'Save':'Create account'}</button><button type="button" class="btn btn-o" onclick="FS.closeModal()">Cancel</button></div></form>`)};
A.staffSave=async(e,id)=>{e.preventDefault();const f=e.target,programs=[...f.querySelectorAll('input[name=pr]:checked')].map(i=>i.value);
 const body={name:f.name.value,programs};if(f.password.value)body.password=f.password.value;if(!f.role.disabled)body.role=f.role.value;
 if(id)await call('PUT','/api/admin/users/'+id,body,'Account updated');else await call('POST','/api/admin/users',{...body,email:f.email.value},'Account created');return false};
A.staffDel=async id=>{if(!confirm('Delete this account? They will no longer be able to log in.'))return;await call('DELETE','/api/admin/users/'+id,undefined,'Account deleted')};

/* ================= Inbox ================= */
function aInbox(){const list=FS.state.messages.slice().reverse();
 return `<div class="card tw"><table class="tbl"><tr><th>Date</th><th>From</th><th>Message</th><th></th></tr>${list.map(m=>`<tr style="${m.read?'':'background:#f7faff'}"><td>${FS.fmt(m.date)}</td><td><b>${E(m.name)}</b>${m.read?'':' <span class="tag a">New</span>'}<br>${mailto(m.email)}</td><td style="max-width:460px;white-space:pre-wrap">${E(m.message)}</td><td><div class="row" style="gap:6px"><button class="btn btn-o btn-sm" onclick="A.msgRead('${m.id}')">${m.read?'Mark unread':'Mark read'}</button>${delBtn(`A.msgDel('${m.id}')`,'✕')}</div></td></tr>`).join('')||'<tr><td colspan="4" class="empty">No messages yet</td></tr>'}</table></div>`}
A.msgRead=async id=>{const m=FS.state.messages.find(x=>x.id===id);m.read=!m.read;await commit()};
A.msgDel=async id=>{if(!confirm('Delete this message?'))return;FS.state.messages=FS.state.messages.filter(x=>x.id!==id);await commit()};

/* ================= Reports ================= */
function aReports(){const S=FS.state,P=FS.programs();
 const by=fn=>P.map(p=>{const st=S.students.filter(s=>s.program===p.id);return [p.name.split(' ')[0],st.length?Math.round(st.reduce((a,s)=>a+fn(s),0)/st.length):0]});
 const completed=S.students.filter(s=>FS.progressOf(s)>=S.criteria.progress).length;
 const ps=['Applied','Shortlisted','Interview Scheduled','Selected','Rejected'];
 const paid=S.students.filter(s=>s.feeStatus==='Paid').length;
 return `<div class="row sp-b" style="margin-bottom:16px"><span class="hint">Live from the database</span><div class="row"><button class="btn btn-o btn-sm" onclick="A.csv()">⬇ Students CSV</button><button class="btn btn-o btn-sm" onclick="A.csvApps()">⬇ Applications CSV</button></div></div>
 <div class="grid g4" style="margin-bottom:22px">${stat('👥',S.students.length,'Total registered students')}${stat('✅',S.students.filter(s=>s.status==='Active').length,'Active enrollments')}${stat('🎓',completed+' ('+FS.pct(completed,S.students.length)+'%)','Program completion')}${stat('🏅',S.certs.length,'Certificates issued')}</div>
 <div class="grid g4" style="margin-bottom:22px">${stat('💳',paid+' / '+S.students.length,'Fees marked paid')}${stat('💰','₹'+(paid*FS.FEE).toLocaleString('en-IN'),'Collected (fee × paid)')}${stat('📥',S.applications.length,'Applications received')}${stat('✔️',S.applications.filter(a=>a.status==='Approved').length,'Applications approved')}</div>
 <div class="grid g2"><div class="card"><h3>Program-wise enrollment</h3>${FS.chart(P.map(p=>[p.name.split(' ')[0],S.students.filter(s=>s.program===p.id).length,S.students.filter(s=>s.program===p.id).length*25]))}</div>
 <div class="card"><h3>Attendance by program (%)</h3>${FS.chart(by(s=>s.attendance),'%')}</div>
 <div class="card"><h3>Assessment performance (avg %)</h3>${FS.chart(by(FS.scoreOf),'%')}</div>
 <div class="card"><h3>Average completion (%)</h3>${FS.chart(by(FS.progressOf),'%')}</div></div>
 <div class="card" style="margin-top:22px"><h3 style="margin-bottom:10px">Placement statistics</h3><div class="grid g4">${[['Openings',S.jobs.length],['Applications',S.jobApps.length],['Interviews',S.interviews.length],['Selected',S.jobApps.filter(a=>a.status==='Selected').length]].map(x=>stat('💼',x[1],x[0])).join('')}</div><div class="pill-row" style="margin-top:14px">${ps.map(x=>`<span class="tag m">${x}: ${S.jobApps.filter(a=>a.status===x).length}</span>`).join('')}</div></div>`}
const csvOut=(name,rows)=>FS.download(name,rows.map(r=>r.map(c=>{let v=String(c==null?'':c);if(/^[=+\-@]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"'}).join(',')).join('\n'),'text/csv');
A.csv=()=>csvOut('finsang_students_report.csv',[['ID','Name','Email','Phone','Program','Progress','Attendance','Score','Fee','Status']].concat(FS.state.students.map(s=>[s.id,s.name,s.email,s.phone||'',FS.pname(s.program),FS.progressOf(s),s.attendance,FS.scoreOf(s),s.feeStatus||'Pending',s.status])));
A.csvApps=()=>csvOut('finsang_applications.csv',[['ID','Name','Email','Phone','City','College','Qualification','Year','Program','Status','Date']].concat(FS.state.applications.map(a=>[a.id,a.name,a.email,a.phone,a.city,a.college,a.qualification,a.year,FS.pname(a.program),a.status,a.date])));

/* ================= Settings ================= */
function aSettings(){const s=FS.state.site;
 return `<div class="grid g2" style="align-items:start"><div class="card"><h3>Site & admissions</h3><form onsubmit="return A.siteSave(event)" style="margin-top:12px"><div class="fg"><label>Program fee (₹, one-time)</label><input name="fee" type="number" min="0" required value="${s.fee}"></div><div class="fg"><label>Contact email</label><input name="email" type="email" value="${E(s.email)}"></div><div class="fg"><label>Contact phone</label><input name="phone" value="${E(s.phone)}"></div><div class="fg"><label>Address</label><textarea name="address">${E(s.address)}</textarea></div><div class="fg"><label>New applications</label>${sel('open',[['1','Open — accepting applications'],['0','Closed']],s.applicationsOpen?'1':'0')}</div><button class="btn btn-p">Save settings</button></form></div>
 <div>${critCard()}<div class="card" style="margin-top:18px"><h3>Data & security</h3><p style="margin:8px 0 12px;font-size:.9rem">Download a full JSON backup of all records (passwords are never included). Uploaded files live in the server's <code>data/uploads</code> folder.</p><div class="row"><a class="btn btn-o" href="/api/admin/backup">⬇ Download backup</a><button class="btn btn-o" onclick="A.pwForm()">Change my password</button></div></div></div></div>`}
A.siteSave=async e=>{e.preventDefault();const f=e.target;FS.state.site={id:'site',fee:+f.fee.value||0,email:f.email.value,phone:f.phone.value,address:f.address.value,applicationsOpen:f.open.value==='1'};await commit('Settings saved');return false};
